  taskType: string,
  examples: Array<{
    problem: string;
    steps: string[];
    finalAnswer: string;
  }>,
  newProblem: string
): string {
  let prompt = `Hãy giải quyết các vấn đề ${taskType} theo từng bước suy luận.\n\n`;
  
  for (let i = 0; i < examples.length; i++) {
