# services/run_service.py - Run management
from openai import OpenAI
from typing import List, Dict, Any, Optional
from enum import Enum

class RunStatus(Enum):
    QUEUED = 'queued'
    IN_PROGRESS = 'in_progress'
    REQUIRES_ACTION = 'requires_action'
    CANCELLING = 'cancelling'
    CANCELLED = 'cancelled'
    FAILED = 'failed'
    COMPLETED = 'completed'
    EXPIRED = 'expired'

@dataclass
class RunResult:
    run_id: str
    status: str
    messages: List[Dict[str, Any]]
    tools_used: Optional[List[str]] = None
    error: Optional[str] = None

@dataclass
class ToolCall:
    id: str
    type: str
    function: Dict[str, str]

class RunService:
    """Service for managing assistant runs."""
    
    def __init__(self, client: OpenAI):
        self.client = client
    
    def create_run(
        self,
        thread_id: str,
        assistant_id: str,
        model: Optional[str] = None,
        instructions: Optional[str] = None,
        tools: Optional[List[Dict[str, Any]]] = None,
        temperature: Optional[float] = None,
        metadata: Optional[Dict[str, Any]] = None,
    ) -> str:
        """Create a new run."""
        params = {'assistant_id': assistant_id}
        
        if model:
            params['model'] = model
        if instructions:
            params['instructions'] = instructions
        if tools:
            params['tools'] = tools
        if temperature is not None:
            params['temperature'] = temperature
        if metadata:
            params['metadata'] = metadata
        
        run = self.client.beta.threads.runs.create(thread_id, **params)
        return run.id
    
    def get_run(self, thread_id: str, run_id: str) -> Dict[str, Any]:
        """Get run details."""
        return self.client.beta.threads.runs.retrieve(thread_id, run_id)
    
    def list_runs(
        self,
        thread_id: str,
        limit: int = 20,
        status: Optional[str] = None,
    ) -> List[Dict[str, Any]]:
        """List runs for a thread."""
        params = {'limit': limit}
        if status:
            params['status'] = status
        
        runs = self.client.beta.threads.runs.list(thread_id, **params)
        return runs.data
    
    def submit_tool_outputs(
        self,
        thread_id: str,
        run_id: str,
        tool_outputs: List[Dict[str, str]],
    ) -> Dict[str, Any]:
        """Submit tool outputs for a run."""
        return self.client.beta.threads.runs.submit_tool_outputs(
            thread_id,
            run_id,
            tool_outputs=tool_outputs,
        )
    
    def cancel_run(self, thread_id: str, run_id: str) -> Dict[str, Any]:
        """Cancel a running operation."""
        return self.client.beta.threads.runs.cancel(thread_id, run_id)
    
    def wait_for_run(
        self,
        thread_id: str,
        run_id: str,
        on_progress: Optional[callable] = None,
        poll_interval_seconds: float = 1.0,
    ) -> RunResult:
        """Wait for run to complete."""
        import time
        
        while True:
            run = self.get_run(thread_id, run_id)
            
            if on_progress:
                on_progress(run.status)
            
            if run.status == 'completed':
                # Get messages after this run
                messages = self.client.beta.threads.messages.list(
                    thread_id,
                    order='asc',
                    after=f'run-{run_id}',
                )
                
                return RunResult(
                    run_id=run.id,
                    status=run.status,
                    messages=messages.data,
                    tools_used=[t.id for t in run.tools] if run.tools else None,
                )
            
            if run.status == 'requires_action':
                tool_calls = (
                    run.required_action.submit_tool_outputs.tool_calls
                    if run.required_action
                    else []
                )
                
                return RunResult(
                    run_id=run.id,
                    status=run.status,
                    messages=[],
                    tools_used=[tc.function.name for tc in tool_calls],
                )
            
            if run.status in ['failed', 'cancelled', 'expired']:
                raise RuntimeError(
                    f"Run {run.status}: {getattr(run.last_error, 'message', 'Unknown error')}"
                )
            
            if run.status == 'cancelling':
                time.sleep(poll_interval_seconds)
                continue
            
            # queued or in_progress - wait
            time.sleep(poll_interval_seconds)
